WITH "match_0" AS MATERIALIZED (SELECT "entity_id" AS "match_0_entity_id", "attr_id" AS "match_0_attr_id", "value" AS "match_0_value", "eav" AS "match_0_is_ref_val", "created_at" AS "match_0_created_at" FROM "triples" AS "t0" WHERE (("app_id" = $1) AND ("ea" = $2) AND ("attr_id" = $3))), "match_1" AS MATERIALIZED (SELECT "entity_id" AS "match_1_entity_id", "attr_id" AS "match_1_attr_id", "value" AS "match_1_value", "eav" AS "match_1_is_ref_val", "created_at" AS "match_1_created_at" FROM "triples" AS "t1" WHERE (("app_id" = $4) AND ("ea" = $5) AND ("attr_id" = $6))), "match_2" AS NOT MATERIALIZED (SELECT "match_0".*, "match_1".*, COALESCE("match_0"."match_0_entity_id", "match_1"."match_1_entity_id") AS "match_2_entity_id" FROM "match_0" FULL JOIN "match_1" ON (0 = 1)) SELECT "match_2".* FROM "match_2"
